def validate_policy_type_options(
    options: object,
    expected_values: list[str],
    context: str,
) -> None:
    if not isinstance(options, list):
        fail(f"coverage policy-type options are invalid: {context}")
    actual_values = [option.get("value") for option in options if isinstance(option, dict)]
    actual_labels = [option.get("label") for option in options if isinstance(option, dict)]
    if actual_values != expected_values or actual_labels != expected_values:
        fail(f"coverage policy-type option values are invalid: {context}")


def validate_allianz_worldview_foreign_currency_variable_universal_life_contract(
    record: dict,
    version: dict,
    context: str,
) -> None:
    product_id = str(
        record.get("product_id")
        or version.get("source_product_id")
        or ""
    )
    revision_match = re.fullmatch(
        r"partial-change-(\d+)",
        str(version.get("terms_revision") or ""),
    )
    revision = int(revision_match.group(1)) if revision_match else -1
    expected_product_id = (
        f"218141M31A011{revision:02d}"
        if 9 <= revision <= 34
        else ""
    )
    if revision <= 10:
        expected_phase = "legacy-annual-insurance-amount-abc"
        expected_policy_types = ["甲型", "乙型", "丙型"]
        expected_formulas = {
            "甲型": "max(basic_face_amount * annual_insurance_amount_factor - insurance_deduction_amount, policy_account_value)",
            "乙型": "basic_face_amount + policy_account_value",
            "丙型": "max(basic_face_amount - insurance_deduction_amount, policy_account_value)",
        }
        expected_deduction_options = ["甲型", "丙型"]
        expected_schedule: list[dict[str, object]] = []
        expected_face_amount_label = "基本保險金額"
        expected_formula_inputs = [
            "insurance_deduction_amount",
            "insured_age_at_issue",
            "policy_year",
        ]
    else:
        expected_phase = (
            "preservation-multiplier-abc"
            if revision == 11
            else "preservation-multiplier-abcd"
            if revision <= 24
            else "preservation-multiplier-abcd-minor-account-value-return"
        )
        expected_policy_types = ["A型", "B型", "C型"]
        expected_formulas = {
            "A型": "max(policy_insurance_amount - insurance_deduction_amount, policy_account_value * preservation_multiplier)",
            "B型": "max(policy_insurance_amount + policy_account_value, policy_account_value * preservation_multiplier)",
            "C型": "policy_insurance_amount + policy_account_value",
        }
        if revision >= 12:
            expected_policy_types.append("D型")
            expected_formulas["D型"] = (
                "max(policy_insurance_amount - insurance_deduction_amount, policy_account_value)"
            )
        expected_deduction_options = [
            "A型",
            *(["D型"] if revision >= 12 else []),
        ]
        expected_schedule = [
            {
                "min_age": 15 if revision >= 25 else 0,
                "max_age": 40,
                "factor": 1.3,
            },
            {"min_age": 41, "max_age": 70, "factor": 1.15},
            {"min_age": 71, "max_age": 130, "factor": 1.01},
        ]
        expected_face_amount_label = "保險金額"
        expected_formula_inputs = [
            "insurance_deduction_amount",
            "insured_age_at_event",
        ]

    expected_inputs = list(
        dict.fromkeys(
            [
                "basic_face_amount",
                "policy_type",
                "maturity_policy_account_value",
                "benefit_valuation_policy_account_value",
                "policy_effect_status_at_event",
                "policy_loan_and_interest_amount",
                "unpaid_monthly_deduction_amount",
                "post_event_insurance_cost_refund_status",
                "post_event_insurance_cost_refund_amount",
                "contract_currency",
                *expected_formula_inputs,
                *(["insured_age_at_event"] if revision >= 25 else []),
            ]
        )
    )
    source_sha = str(version.get("source_document_sha256") or "")
    outer_source_sha = str(record.get("source_document_sha256") or "")
    if (
        product_id != expected_product_id
        or version.get("source_product_id") != product_id
        or version.get("source_batch_id") != "tii-life-095"
        or version.get("product_family")
        != "allianz-worldview-foreign-currency-variable-universal-life"
        or version.get("company_group") != "allianz_life"
        or version.get("source_text_quality")
        != "machine_readable_exact_hash"
        or version.get("source_text_extractor") != "pypdf"
        or not re.fullmatch(r"[0-9a-f]{64}", source_sha)
        or (
            outer_source_sha
            and outer_source_sha != source_sha
        )
        or not isinstance(version.get("source_page_count"), int)
        or isinstance(version.get("source_page_count"), bool)
        or version["source_page_count"] <= 0
        or record.get("selection_type") != "face_amount_plan"
        or record.get("input_mode") != "face_amount_plan"
        or record.get("face_amount_label") != expected_face_amount_label
        or version.get("semantic_phase") != expected_phase
        or version.get("currency_basis") != "policy_foreign_currency"
        or version.get("payment_currency_label") != "約定外幣"
        or version.get("contract_currency_code_format")
        != "iso_4217_alpha3"
        or version.get("same_currency_amount_inputs_required") is not True
        or version.get("money_decimal_places") != 4
        or version.get("maturity_trigger") != "age_111_policy_anniversary"
        or version.get("maturity_age") != 111
        or version.get("policy_type_options") != expected_policy_types
        or version.get("formula_by_type") != expected_formulas
        or version.get(
            "insurance_deduction_amount_policy_type_options"
        )
        != expected_deduction_options
        or version.get("preservation_multiplier_schedule")
        != expected_schedule
        or version.get("threshold_factor_schedule")
        != expected_schedule
        or version.get("required_policy_inputs") != expected_inputs
    ):
        fail(f"coverage Allianz Worldview version contract is invalid: {context}")

    expected_legacy_rule = (
        "100_percent_plus_5_percent_per_policy_year_capped_at_attained_age_60"
        if revision <= 10
        else None
    )
    if (
        version.get("annual_insurance_amount_factor_rule")
        != expected_legacy_rule
        or version.get("annual_insurance_amount_table_issue_age_min")
        != (14 if revision <= 10 else None)
        or version.get("annual_insurance_amount_table_attained_age_cap")
        != (60 if revision <= 10 else None)
    ):
        fail(f"coverage Allianz Worldview legacy table contract is invalid: {context}")

    expected_true_flags = {
        "foreign_currency_policy",
        "contract_currency_required",
        "investment_linked_policy",
        "variable_universal_life_policy",
        "age111_maturity",
        "policy_account_value_required",
        "policy_effect_status_required",
        "policy_loan_offset_applies",
        "unpaid_monthly_deduction_offset_applies",
        "post_event_insurance_cost_refund_applies",
        "account_value_return_on_time_bar",
        "account_value_return_on_exclusion",
        "non_participating_policy",
    }
    if any(version.get(flag) is not True for flag in expected_true_flags):
        fail(f"coverage Allianz Worldview flags are invalid: {context}")
    has_minor_return = revision >= 25
    if (
        version.get("minor_death_before_age_15_account_value_rule")
        is not has_minor_return
        or version.get(
            "minor_disability_before_age_15_account_value_rule"
        )
        is not has_minor_return
        or version.get("complete_disability_table_item_count") != 7
        or version.get("disability_term") != "殘廢"
    ):
        fail(f"coverage Allianz Worldview age/disability contract is invalid: {context}")

    validate_policy_type_options(
        record.get("plan_options"),
        expected_policy_types,
        context,
    )
    shared_offset_state_keys = [
        "policy_effect_status_at_event",
        "policy_loan_and_interest_amount",
        "unpaid_monthly_deduction_amount",
    ]
    maturity_state_keys = [
        "maturity_policy_account_value",
        *shared_offset_state_keys,
    ]
    claim_state_keys = [
        "benefit_valuation_policy_account_value",
        *shared_offset_state_keys,
        "post_event_insurance_cost_refund_status",
        "post_event_insurance_cost_refund_amount",
    ]
    minor_age = 15 if has_minor_return else None
    validate_exact_coverage_entry_contract(
        record.get("coverage_entries"),
        {
            "maturity-benefit": {
                "calculation_basis":
                    "net_amount_at_risk_plus_policy_account_value",
                "policy_state_keys": maturity_state_keys,
                "currency_state_key": "contract_currency",
            },
            "death-benefit": {
                "calculation_basis":
                    "net_amount_at_risk_plus_policy_account_value",
                "policy_state_keys": claim_state_keys,
                "currency_state_key": "contract_currency",
                "minor_account_value_return_age": minor_age,
            },
            "total-disability-benefit": {
                "calculation_basis":
                    "net_amount_at_risk_plus_policy_account_value",
                "policy_state_keys": claim_state_keys,
                "currency_state_key": "contract_currency",
                "minor_account_value_return_age": minor_age,
            },
        },
        context,
    )


