def validate_shinkong_jinmanyi_variable_universal_life_contract(
    record: dict,
    version: dict,
    context: str,
) -> None:
    product_id = str(
        record.get("product_id")
        or version.get("source_product_id")
        or ""
    )
    revision_match = re.fullmatch(
        r"partial-change-(\d+)",
        str(version.get("terms_revision") or ""),
    )
    revision = int(revision_match.group(1)) if revision_match else -1
    expected_product_id = (
        f"208121M31A007{revision:02d}"
        if 0 <= revision <= 23
        else ""
    )
    source_sha = str(version.get("source_document_sha256") or "")
    outer_source_sha = str(record.get("source_document_sha256") or "")
    expected_unit_keys = {
        "shinkong_jinmanyi_maturity_benefit",
        "shinkong_jinmanyi_death_benefit",
        "shinkong_jinmanyi_total_disability_benefit",
    }
    expected_phase = (
        "age14-risk-threshold-appendix5"
        if revision <= 12
        else "age15-minor-return-death-before-maturity-appendix5"
        if revision == 13
        else (
            "age15-minor-return-death-before-maturity-"
            "minor-exclusion-clause-appendix5"
        )
        if revision <= 17
        else (
            "age15-minor-return-all-events-before-maturity-"
            "minor-exclusion-clause-appendix5"
        )
        if revision <= 21
        else (
            "age15-minor-return-all-events-before-maturity-"
            "minor-exclusion-clause-appendix4"
        )
    )
    entries = record.get("coverage_entries")
    actual_unit_keys = (
        {
            str(entry.get("unit_key") or "")
            for entry in entries
            if isinstance(entry, dict)
        }
        if isinstance(entries, list)
        else set()
    )
    if (
        product_id != expected_product_id
        or version.get("source_product_id") != product_id
        or version.get("source_batch_id") != "tii-life-047"
        or version.get("product_family")
        != "shinkong-jinmanyi-variable-universal-life"
        or version.get("source_text_extractor") != "pypdf"
        or not re.fullmatch(r"[0-9a-f]{64}", source_sha)
        or (outer_source_sha and outer_source_sha != source_sha)
        or version.get("semantic_phase") != expected_phase
        or version.get("minor_exclusion_account_value_return_clause")
        is not (revision >= 14)
        or actual_unit_keys != expected_unit_keys
    ):
        fail(
            "coverage Shinkong Jinmanyi exact-version identity is invalid: "
            f"{context}"
        )

    effective_revision = revision + 1
    synthetic_product_id = (
        f"208121M31A006{effective_revision:02d}"
    )
    synthetic_record = deepcopy(record)
    synthetic_version = deepcopy(version)
    synthetic_record["product_id"] = synthetic_product_id
    synthetic_entries = deepcopy(entries)
    for entry in synthetic_entries:
        entry["unit_key"] = str(entry.get("unit_key") or "").replace(
            "shinkong_jinmanyi_",
            "shinkong_jinhaoyi_",
        )
    synthetic_record["coverage_entries"] = synthetic_entries
    synthetic_version.update(
        {
            "product_family":
                "shinkong-jinhaoyi-variable-universal-life",
            "source_product_id": synthetic_product_id,
            "terms_revision": f"partial-change-{effective_revision}",
            "semantic_phase": (
                "age14-risk-threshold-appendix5"
                if effective_revision <= 13
                else (
                    "age15-minor-return-death-before-maturity-"
                    "appendix5"
                )
                if effective_revision <= 18
                else (
                    "age15-minor-return-all-events-before-maturity-"
                    "appendix5"
                )
                if effective_revision <= 22
                else (
                    "age15-minor-return-all-events-before-maturity-"
                    "appendix4"
                )
            ),
            "source_text_extractor": (
                "pymupdf"
                if effective_revision == 3
                else "pypdf"
            ),
        }
    )
    validate_shinkong_jinhaoyi_variable_universal_life_contract(
        synthetic_record,
        synthetic_version,
        f"{context} (Jinmanyi semantic revision {effective_revision})",
    )


def validate_bnp_paribas_legacy_recorded_variable_life_contract(
    record: dict,
    version: dict,
    context: str,
) -> None:
    product_id = str(
        record.get("product_id")
        or version.get("source_product_id")
        or ""
    )
    outer_source_document_sha256 = str(
        record.get("source_document_sha256") or ""
    )
    version_source_document_sha256 = str(
        version.get("source_document_sha256") or ""
    )
    if (
        outer_source_document_sha256
        and outer_source_document_sha256
        != version_source_document_sha256
    ):
        fail(f"BNP legacy recorded source PDF hash is invalid: {context}")
    family_by_prefix = {
        "267191M31A009": (
            "top-player-twd",
            "paid_premium_factor",
            "twd",
            6,
        ),
        "267191M31A008": (
            "investment-expert",
            "paid_premium_factor",
            "twd",
            5,
        ),
        "267191M31A010": (
            "flagship-100",
            "paid_premium_factor",
            "twd",
            5,
        ),
        "267191M31A012": (
            "flagship-100-one",
            "paid_premium_factor",
            "twd",
            6,
        ),
        "267191M31A013": (
            "investment-expert-foreign",
            "paid_premium_factor",
            "foreign_currency",
            4,
        ),
        "267191M31A014": (
            "top-player-foreign",
            "paid_premium_factor",
            "foreign_currency",
            6,
        ),
        "267191M31A015": (
            "wealth-expert",
            "paid_premium_factor",
            "twd",
            4,
        ),
        "267191M31A016": (
            "wealth-expert-foreign",
            "paid_premium_factor",
            "foreign_currency",
            4,
        ),
        "267191M31A017": (
            "top-100",
            "paid_premium_factor",
            "twd",
            5,
        ),
        "267191M31A018": (
            "top-100-foreign",
            "paid_premium_factor",
            "foreign_currency",
            5,
        ),
        "267191M31A019": (
            "value-100",
            "three_way_recorded_amounts",
            "twd",
            6,
        ),
    }
    prefix = product_id[:-2]
    family_contract = family_by_prefix.get(prefix)
    revision_text = product_id[-2:]
    if (
        family_contract is None
        or not revision_text.isdigit()
        or int(revision_text) not in range(family_contract[3])
    ):
        fail(f"BNP legacy recorded product identity is invalid: {context}")
    family_key, formula_variant, currency_basis, _revision_count = (
        family_contract
    )
    revision = int(revision_text)
    foreign_currency = currency_basis == "foreign_currency"
    expected_terms_revision = (
        "original" if revision == 0 else f"partial_change_{revision}"
    )
    expected_common = {
        "source_product_id": product_id,
        "source_document_sha256": version_source_document_sha256,
        "product_family": "bnp-paribas-legacy-recorded-variable-life",
        "product_family_key": family_key,
        "company_group": "bnp_paribas_cardif_life",
        "terms_revision": expected_terms_revision,
        "currency_basis": currency_basis,
        "contract_currency_required": foreign_currency,
        "remittance_fee_required": foreign_currency,
        "investment_linked_policy": True,
        "variable_life_policy": True,
        "maturity_trigger": "age_110_policy_anniversary",
        "maturity_benefit_formula":
            "maturity_policy_account_value_at_next_valuation_date_minus_offsets",
        "benefit_valuation_policy_account_value_required": True,
        "policy_effect_status_required": True,
        "policy_offsets_required": True,
        "funeral_benefit_limit_rule": True,
        "funeral_benefit_excludes_account_value": True,
        "minor_death_before_age_15_account_value_rule": True,
        "minor_disability_before_age_15_account_value_rule": True,
        "complete_disability_table_item_count": 7,
        "disability_term": "殘廢",
        "non_participating_policy": True,
        "input_formula_variant": formula_variant,
    }
    if formula_variant == "paid_premium_factor":
        expected_common["specified_factor_unit_required"] = True
    if any(version.get(field) != value for field, value in expected_common.items()):
        fail(f"BNP legacy recorded version contract is invalid: {context}")
    if (
        not re.fullmatch(
            r"[0-9a-f]{64}",
            version_source_document_sha256,
        )
        or not re.fullmatch(
            r"[0-9a-f]{64}",
            str(version.get("source_text_sha256") or ""),
        )
        or version.get("source_text_extractor") not in {"pypdf", "pymupdf"}
        or not isinstance(version.get("source_page_count"), int)
        or isinstance(version.get("source_page_count"), bool)
        or version["source_page_count"] <= 0
    ):
        fail(f"BNP legacy recorded source text contract is invalid: {context}")

    maturity_state_keys = [
        "maturity_policy_account_value",
        "policy_effect_status_at_event",
        "policy_loan_and_interest_amount",
        "unpaid_policy_charge_amount",
    ]
    common_event_offset_keys = [
        "benefit_valuation_policy_account_value",
        "policy_effect_status_at_event",
        "policy_loan_and_interest_amount",
        "unpaid_policy_charge_amount",
        "claim_time_status",
        "benefit_exclusion_status",
    ]
    if foreign_currency:
        maturity_state_keys.append("remittance_fee_amount")

    if formula_variant == "paid_premium_factor":
        death_event_keys = [
            *common_event_offset_keys,
            "death_benefit_status",
            "remaining_funeral_benefit_limit",
            "funeral_excess_insurance_cost_refund_status",
            "funeral_excess_insurance_cost_refund_amount",
        ]
        disability_event_keys = [
            *common_event_offset_keys,
            "total_disability_qualification_status",
        ]
        if foreign_currency:
            death_event_keys.append("remittance_fee_amount")
            disability_event_keys.append("remittance_fee_amount")
        validate_policy_type_options(
            record.get("plan_options"),
            ["甲型", "乙型"],
            context,
        )
        expected_inputs = [
            "policy_type",
            "paid_premium_total",
            "partial_termination_amount_total",
            "specified_percent_or_multiplier",
            "specified_factor_unit",
            "benefit_valuation_policy_account_value",
            "insured_age_at_event",
            "policy_effect_status_at_event",
            "claim_time_status",
            "benefit_exclusion_status",
            "policy_loan_and_interest_amount",
            "unpaid_policy_charge_amount",
            "death_benefit_status",
            "remaining_funeral_benefit_limit",
            "funeral_excess_insurance_cost_refund_status",
            "funeral_excess_insurance_cost_refund_amount",
            "total_disability_qualification_status",
            "maturity_policy_account_value",
        ]
        if foreign_currency:
            expected_inputs.extend(
                ["contract_currency", "remittance_fee_amount"]
            )
        if (
            record.get("selection_type") != "paid_premium_factor_plan"
            or record.get("input_mode") != "paid_premium_factor_plan"
            or version.get("policy_type_options") != ["甲型", "乙型"]
            or version.get("required_policy_inputs") != expected_inputs
            or set(version.get("formula_by_type") or {}) != {"甲型", "乙型"}
        ):
            fail(f"BNP legacy paid-premium input contract is invalid: {context}")
        expected_entries = {
            "maturity-benefit": {
                "calculation_basis": "maturity_policy_account_value",
                "policy_state_keys": maturity_state_keys,
                "currency_state_key": (
                    "contract_currency" if foreign_currency else None
                ),
            },
            "death-or-funeral-benefit": {
                "calculation_basis":
                    "paid_premium_factor_account_value_formula",
                "policy_state_keys": death_event_keys,
                "currency_state_key": (
                    "contract_currency" if foreign_currency else None
                ),
                "minor_account_value_return_age": 15,
                "funeral_limit_plan_options": ["甲型", "乙型"],
            },
            "total-disability-benefit": {
                "calculation_basis":
                    "paid_premium_factor_account_value_formula",
                "policy_state_keys": disability_event_keys,
                "currency_state_key": (
                    "contract_currency" if foreign_currency else None
                ),
                "minor_account_value_return_age": 15,
            },
        }
    else:
        value_addition_keys = [
            "installment_premium_frequency",
            "previous_installment_premium_cumulative_count",
            "current_installment_premium_cumulative_count",
            "previous_installment_premium_average_amount",
            "value_addition_qualification_status",
        ]
        expected_inputs = [
            "current_policy_amount",
            "basic_face_amount",
            "benefit_valuation_policy_account_value",
            "insured_age_at_event",
            "policy_effect_status_at_event",
            "policy_loan_and_interest_amount",
            "unpaid_policy_charge_amount",
            "death_benefit_status",
            "remaining_funeral_benefit_limit",
            "maturity_policy_account_value",
            *value_addition_keys,
        ]
        candidate_and_offset_keys = [
            "current_policy_amount",
            "basic_face_amount",
            "benefit_valuation_policy_account_value",
            "policy_effect_status_at_event",
            "policy_loan_and_interest_amount",
            "unpaid_policy_charge_amount",
        ]
        if (
            record.get("selection_type") != "policy_state"
            or record.get("input_mode") != "policy_state"
            or record.get("plan_options") is not None
            or version.get("policy_type_options") != ["丙型"]
            or version.get("required_policy_inputs") != expected_inputs
            or set(version.get("formula_by_type") or {}) != {"丙型"}
            or version.get("value_addition_rate_bands")
            != [
                {"count_range": "0-60", "rate_percent": 0},
                {"count_range": "61-120", "rate_percent": 1},
                {"count_range": "121+", "rate_percent": 2},
            ]
            or version.get("value_addition_credit_destination")
            != "twd_money_account"
            or version.get(
                "value_addition_already_reflected_in_account_value_after_credit"
            )
            is not True
        ):
            fail(f"BNP legacy Value100 input contract is invalid: {context}")
        expected_entries = {
            "maturity-benefit": {
                "calculation_basis": "maturity_policy_account_value",
                "policy_state_keys": maturity_state_keys,
            },
            "death-or-funeral-benefit": {
                "calculation_basis": "death_or_funeral_greater_of",
                "policy_state_keys": candidate_and_offset_keys,
                "minor_account_value_return_age": 15,
            },
            "total-disability-benefit": {
                "calculation_basis": "greater_of",
                "policy_state_keys": candidate_and_offset_keys,
                "minor_account_value_return_age": 15,
            },
            "value-added-benefit": {
                "calculation_basis": "installment_premium_value_addition",
                "policy_state_keys": value_addition_keys,
                "amount_role": "reference",
                "unit_key": "installment_premium_value_addition",
            },
        }
    validate_exact_coverage_entry_contract(
        record.get("coverage_entries"),
        expected_entries,
        context,
    )


def validate_hongtai_lehuo_variable_annuity_contract(
    record: dict,
    version: dict,
    context: str,
) -> None:
    revision_match = re.fullmatch(
        r"partial-change-(\d+)",
        str(version["terms_revision"]),
    )
    revision = int(revision_match.group(1)) if revision_match else -1
    allowed_revisions = {
        3,
        12,
        14,
        21,
        *range(24, 35),
        *range(36, 42),
    }
    expected_product_id = (
        f"217421M31A001{revision:02d}"
        if revision <= 28
        else f"217421MV1A00123A11Z900000{revision:02d}"
    )
    expected_extractor = (
        "pymupdf"
        if revision in {28, 30, 32, 33, 37, 41}
        else "pypdf"
    )
    expected_quality = (
        "machine_readable_exact_hash_pymupdf_recovery"
        if expected_extractor == "pymupdf"
        else "machine_readable_exact_hash"
    )
    modern_articles = revision >= 28
    expected_articles = (
        {
            "start": "第十六條",
            "payment_method": "第十七條",
            "annuity_amount": "第十八條",
            "partial_withdrawal": "第二十條",
            "death_return": "第二十一條",
        }
        if modern_articles
        else {
            "start": "第九條",
            "payment_method": "第十條",
            "annuity_amount": "第十一條",
            "partial_withdrawal": "第十三條",
            "death_return": "第十九條",
        }
    )
    expected_inputs = [
        "annuity_payment_option",
        "annuity_start_policy_account_value",
        "annuity_payment_amount",
        "benefit_valuation_policy_account_value",
        "excess_annuity_reserve_return_amount",
        "unpaid_annuity_balance",
    ]
    if (
        revision not in allowed_revisions
        or version["product_family"]
        != "hongtai-lehuo-variable-annuity"
        or version["company_group"] != "hongtai_life"
        or version["source_product_id"] != expected_product_id
        or not re.fullmatch(
            r"[0-9a-f]{64}",
            str(version["source_document_sha256"]),
        )
        or version["source_text_quality"] != expected_quality
        or version["source_text_extractor"] != expected_extractor
        or version["semantic_phase"]
        != (
            "modern-annuity-notice-and-payment-articles"
            if modern_articles
            else "legacy-annuity-payment-articles"
        )
        or version["article_numbers"] != expected_articles
        or version["annuity_start_payment_deadline_days"]
        != (15 if modern_articles else None)
        or version["annuity_start_delay_interest_rule"]
        is not modern_articles
        or version["currency_basis"] != "twd"
        or version["payment_currency_label"] != "新臺幣"
        or version["annuity_payment_options"]
        != ["一次給付", "分期給付"]
        or version["annuity_amount_formula"]
        != "insurer_calculated_from_annuity_start_account_value_less_policy_loan_using_assumed_interest_rate_life_table_and_guarantee_period"
        or version["guarantee_period_options_years"] != [10, 15, 20]
        or version["minimum_accumulation_period_years"] != 10
        or version["default_annuity_start_age"] != 70
        or version["max_annuity_start_age"] != 80
        or version["max_annuity_payment_age"] != 110
        or version["minimum_annual_annuity_amount"] != 10_000
        or version["maximum_annual_annuity_amount"] != 1_200_000
        or version["minimum_partial_withdrawal_amount"] != 5_000
        or version["minimum_remaining_account_value"] != 10_000
        or version["required_policy_inputs"] != expected_inputs
    ):
        fail(
            "coverage Hongtai Lehuo variable annuity version "
            f"contract is invalid: {context}"
        )
    if any(
        version[flag] is not True
        for flag in (
            "investment_linked_policy",
            "annuity_policy",
            "pre_annuity_death_account_value_return",
            "post_annuity_death_unpaid_balance",
            "non_participating_policy",
        )
    ):
        fail(
            "coverage Hongtai Lehuo variable annuity boolean "
            f"flag is invalid: {context}"
        )
    if (
        record.get("selection_type") != "plan"
        or record.get("input_mode") != "plan"
        or record.get("selection_label") != "年金給付方式"
    ):
        fail(
            "coverage Hongtai Lehuo variable annuity input mode "
            f"is invalid: {context}"
        )
    validate_policy_type_options(
        record.get("plan_options"),
        ["一次給付", "分期給付"],
        context,
    )
    plan_options_by_value = {
        option.get("value"): option
        for option in record.get("plan_options") or []
        if isinstance(option, dict)
    }
    common_death_contract = {
        "name": "年金開始前身故返還保單帳戶價值",
        "basis": "policy_recorded_limit",
        "calculation_basis": "policy_state_amount",
        "amount_role": "payout",
        "limit_scope": "per_policy",
        "aggregation_rule": "choose_one",
        "event_key": "death_before_annuity_start",
        "unit_key": "benefit_valuation_policy_account_value",
        "policy_state_keys": [
            "benefit_valuation_policy_account_value"
        ],
        "amount_stage": "insurer_quoted_amount",
    }
    validate_exact_coverage_entry_contract(
        plan_options_by_value["一次給付"].get("coverage_entries"),
        {
            "annuity-start-lump-sum": {
                "name": "年金開始日一次給付",
                "basis": "policy_recorded_limit",
                "calculation_basis": "policy_state_amount",
                "amount_role": "payout",
                "limit_scope": "per_policy",
                "aggregation_rule": "choose_one",
                "event_key": "annuity_start",
                "unit_key": "annuity_start_policy_account_value",
                "policy_state_keys": [
                    "annuity_start_policy_account_value"
                ],
                "amount_stage": "insurer_quoted_amount",
            },
            "account-value-return-before-annuity-start-death":
                common_death_contract,
        },
        f"{context} plan 一次給付",
    )
    validate_exact_coverage_entry_contract(
        plan_options_by_value["分期給付"].get("coverage_entries"),
        {
            "annual-annuity-or-low-amount-lump-sum": {
                "name": "分期年金給付（低額時改一次給付）",
                "basis": "policy_recorded_limit",
                "calculation_basis": "annuity_amount_or_lump_sum",
                "amount_role": "payout",
                "limit_scope": "per_policy",
                "aggregation_rule": "choose_one",
                "event_key": "annuity_start_or_annual_payment",
                "unit_key": "annual_annuity_or_lump_sum",
                "policy_state_keys": [
                    "annuity_payment_amount",
                    "annuity_start_policy_account_value",
                ],
                "minimum_annual_annuity_amount": 10_000,
                "maximum_annual_annuity_amount": 1_200_000,
                "amount_stage": "insurer_quoted_amount",
            },
            "excess-account-value-return-at-annuity-start": {
                "name": "年金開始時超額保單帳戶價值返還",
                "basis": "policy_recorded_limit",
                "calculation_basis": "policy_state_amount",
                "amount_role": "payout",
                "limit_scope": "per_policy",
                "aggregation_rule": "conditional_additive",
                "conditional_event_key":
                    "annuity_start_excess_return",
                "applies_to_entry_ids": [
                    "annual-annuity-or-low-amount-lump-sum"
                ],
                "unit_key": "excess_annuity_reserve_return_amount",
                "policy_state_keys": [
                    "excess_annuity_reserve_return_amount"
                ],
                "amount_stage": "insurer_quoted_amount",
            },
            "account-value-return-before-annuity-start-death":
                common_death_contract,
            "unpaid-annuity-balance-after-death": {
                "name": "年金開始後身故之未支領年金餘額",
                "basis": "policy_recorded_limit",
                "calculation_basis": "policy_state_amount",
                "amount_role": "payout",
                "limit_scope": "per_policy",
                "aggregation_rule": "choose_one",
                "event_key": "death_after_annuity_start",
                "unit_key": "unpaid_annuity_balance",
                "policy_state_keys": ["unpaid_annuity_balance"],
                "amount_stage": "insurer_quoted_amount",
            },
        },
        f"{context} plan 分期給付",
    )


